import{_ as d,o as e,c as a,a0 as r}from"./chunks/framework.CLbANrvH.js";const m=JSON.parse('{"title":"支持的模型与后端","description":"","frontmatter":{"title":"支持的模型与后端"},"headers":[],"relativePath":"zh/reference/models.md","filePath":"zh/reference/models.md","lastUpdated":1791849617000}'),o={name:"zh/reference/models.md"};function c(n,t,h,l,i,s){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="支持的模型与后端" tabindex="-1">支持的模型与后端 <a class="header-anchor" href="#支持的模型与后端" aria-label="Permalink to &quot;支持的模型与后端&quot;">​</a></h1><p>本页由权威目录 <a href="https://github.com/iBLOC/neuron/blob/main/src/capabilities/catalog.rs" target="_blank" rel="noreferrer"><code>src/capabilities/catalog.rs</code></a> (<code>default_capabilities()</code>)生成,即 <code>/v1/models</code> 端点返回的全部条目。实测速度与内存数据见 <a href="/neuron/zh/reference/benchmarks">/zh/reference/benchmarks</a>。</p><h2 id="平台默认模型" tabindex="-1">平台默认模型 <a class="header-anchor" href="#平台默认模型" aria-label="Permalink to &quot;平台默认模型&quot;">​</a></h2><p><strong><code>minicpm5-1b</code></strong>(OpenBMB,Apache-2.0)——1B <code>LlamaForCausalLM</code>,131K 上下文, 混合 <code>&lt;think&gt;</code> 推理,candle 路径(CPU f16 或 CUDA bf16)。注册在 <code>candle</code> 引擎下,<code>is_default: true</code>。</p><h2 id="能力-×-模型-×-引擎矩阵" tabindex="-1">能力 × 模型 × 引擎矩阵 <a class="header-anchor" href="#能力-×-模型-×-引擎矩阵" aria-label="Permalink to &quot;能力 × 模型 × 引擎矩阵&quot;">​</a></h2><p>引擎(engine)是配置注册与 <code>/v1/models</code> 使用的 <code>engine_impl</code> 字符串;请求级 推理<em>执行器</em>(如 OCR 内部的 tract 与 ort)单独标注。所有条目需要对应的 feature flag(见 <a href="/neuron/zh/concepts/feature-flags">/zh/concepts/feature-flags</a>)。</p><h3 id="llm-对话、流式、工具调用" tabindex="-1">LLM(对话、流式、工具调用) <a class="header-anchor" href="#llm-对话、流式、工具调用" aria-label="Permalink to &quot;LLM(对话、流式、工具调用)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模型</th><th>引擎</th><th>参数量</th><th>说明</th></tr></thead><tbody><tr><td>qwen2.5-0.5b</td><td>candle</td><td>0.5B</td><td>边缘档</td></tr><tr><td>qwen3-0.6b</td><td>candle</td><td>0.6B</td><td></td></tr><tr><td><strong>minicpm5-1b</strong></td><td>candle</td><td>1B</td><td>平台默认,131K 上下文</td></tr><tr><td>minicpm5-2b</td><td>candle</td><td>2.52B</td><td>bf16 约 6-7 GB 显存</td></tr><tr><td>llama-3-8b</td><td>candle</td><td>8B</td><td></td></tr><tr><td>phi-3-mini</td><td>candle</td><td>3.8B</td><td></td></tr><tr><td>mistral-7b</td><td>candle</td><td>7B</td><td></td></tr><tr><td>chatglm-3-6b</td><td>candle</td><td>6B</td><td></td></tr><tr><td>gemma-3n-e2b-it / e4b-it</td><td>litert</td><td>2B / 4B 有效</td><td>端侧(LiteRT-LM)</td></tr><tr><td>gemma-3-12b-it / gemma-4-e2b-it / gemma-4-e4b-it / gemma-4-12b-it</td><td>litert</td><td>—</td><td>端侧</td></tr><tr><td>minicpm5-1b</td><td>litert</td><td>1B</td><td>同权重,LiteRT 路径</td></tr><tr><td>Qwen/Qwen3-0.6B</td><td>mistralrs</td><td>0.6B</td><td>ISQ 量化(默认 q4_0)</td></tr><tr><td>microsoft/Mage-VL</td><td>mage_vl</td><td>4B</td><td>图像+视频,自研 candle 移植</td></tr></tbody></table><h3 id="tts-语音合成" tabindex="-1">TTS(语音合成) <a class="header-anchor" href="#tts-语音合成" aria-label="Permalink to &quot;TTS(语音合成)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模型</th><th>引擎</th><th>说明</th></tr></thead><tbody><tr><td>voxcpm-0.5b</td><td>burn</td><td>预转换 burn 权重,边缘档</td></tr><tr><td>voxcpm2</td><td>burn</td><td>2.29B,48 kHz,30 语种,声音克隆;约 10 GB 内存(f32)</td></tr></tbody></table><h3 id="asr-语音转文字" tabindex="-1">ASR(语音转文字) <a class="header-anchor" href="#asr-语音转文字" aria-label="Permalink to &quot;ASR(语音转文字)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模型</th><th>引擎</th><th>说明</th></tr></thead><tbody><tr><td>sensevoice-small</td><td>sherpa</td><td>官方 sherpa-onnx 绑定</td></tr><tr><td>sensevoice-small</td><td>tract</td><td>纯 Rust ONNX 路径;需 prep 脚本</td></tr><tr><td>whisper-base</td><td>candle</td><td></td></tr></tbody></table><h3 id="rerank-重排" tabindex="-1">Rerank(重排) <a class="header-anchor" href="#rerank-重排" aria-label="Permalink to &quot;Rerank(重排)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模型</th><th>引擎</th><th>说明</th></tr></thead><tbody><tr><td>bge-reranker-base</td><td>candle</td><td>约 1.08 GB</td></tr><tr><td>mxbai-rerank-base-v2</td><td>candle</td><td></td></tr><tr><td>jina-reranker-base-v2</td><td>candle</td><td></td></tr><tr><td>rerank-english-v3.0 / rerank-multilingual-v3.0</td><td>cohere(托管 API)</td><td>无本地权重;需 <code>NEURON_COHERE_API_KEY</code></td></tr></tbody></table><h3 id="embedding-嵌入向量" tabindex="-1">Embedding(嵌入向量) <a class="header-anchor" href="#embedding-嵌入向量" aria-label="Permalink to &quot;Embedding(嵌入向量)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模型</th><th>引擎</th><th>说明</th></tr></thead><tbody><tr><td>all-minilm-l6-v2</td><td>candle</td><td>约 88 MB,批量前向,base64 输出</td></tr></tbody></table><h3 id="vision-检测-定位" tabindex="-1">Vision(检测/定位) <a class="header-anchor" href="#vision-检测-定位" aria-label="Permalink to &quot;Vision(检测/定位)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模型</th><th>引擎</th><th>说明</th></tr></thead><tbody><tr><td>yolov8n / yolov8s / yolov11n</td><td>candle</td><td>清洁室 YOLOv8 架构;n 约 6 MB</td></tr><tr><td>rtdetr-r50 / detr-resnet50</td><td>candle</td><td>Transformer 检测器,免 NMS</td></tr><tr><td>rf-detr-base / rf-detr-large</td><td>ort</td><td>ONNX 执行器</td></tr><tr><td>florence-2-base</td><td>ort</td><td>提示驱动的 VLM</td></tr></tbody></table><h3 id="ocr-文字检测-识别-可选版面-表格" tabindex="-1">OCR(文字检测 + 识别,可选版面 + 表格) <a class="header-anchor" href="#ocr-文字检测-识别-可选版面-表格" aria-label="Permalink to &quot;OCR(文字检测 + 识别,可选版面 + 表格)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模型</th><th>引擎</th><th>说明</th></tr></thead><tbody><tr><td>ppocrv5-mobile</td><td>paddle-ocr</td><td>检测+识别 约 21 MB</td></tr><tr><td>ppocrv5-server</td><td>paddle-ocr</td><td>检测 88 MB + 识别 85 MB</td></tr><tr><td>ppocrv6-medium</td><td>paddle-ocr</td><td>检测 62 MB + 识别 77 MB,50 语种</td></tr></tbody></table><p>引擎的会话执行器可插拔:<code>tract</code>(纯 Rust,默认)或 <code>ort</code>(onnxruntime, 约快 10×)。同目录可选附加模型:<code>rec-&lt;pack&gt;/</code> 语种包(109 种文字)、 <code>layout.onnx</code>(PP-DocLayoutV3,约 130 MB)、<code>table.onnx</code>(SLANeXt,约 368 MB)。 详见 <a href="/neuron/zh/howto/ocr">/zh/howto/ocr</a>。</p><h3 id="决策打分——运行时就绪-未入默认目录" tabindex="-1">决策打分——运行时就绪,未入默认目录 <a class="header-anchor" href="#决策打分——运行时就绪-未入默认目录" aria-label="Permalink to &quot;决策打分——运行时就绪,未入默认目录&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模型</th><th>引擎</th><th>说明</th></tr></thead><tbody><tr><td>laya(含 multilingual、typed-decisions)</td><td>tract</td><td>int8 纯编码器 ONNX,约 500 MB;经 <code>NEURON_DECISION_MODEL_PATH</code> 注册;需 prep 脚本</td></tr></tbody></table><h3 id="时序预测——运行时就绪-未入默认目录" tabindex="-1">时序预测——运行时就绪,未入默认目录 <a class="header-anchor" href="#时序预测——运行时就绪-未入默认目录" aria-label="Permalink to &quot;时序预测——运行时就绪,未入默认目录&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模型</th><th>引擎</th><th>说明</th></tr></thead><tbody><tr><td>chronos2</td><td>candle(chronos2 feature)</td><td>自研移植的 T5 型编码器/解码器;经 <code>NEURON_CHRONOS2_MODEL_PATH</code> 注册</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">目录 vs 运行时</p><p>Decision 与 Chronos2 有完整运行时实现和 HTTP 端点,但没有默认目录条目—— 因为没有可直接下载即用的权重(Laya 需要走导出/prep 流程,Chronos2 需要 checkpoint)。请通过环境变量显式注册,见 <a href="/neuron/zh/reference/env-vars">/zh/reference/env-vars</a>。</p></div><h2 id="引擎命名" tabindex="-1">引擎命名 <a class="header-anchor" href="#引擎命名" aria-label="Permalink to &quot;引擎命名&quot;">​</a></h2><p><code>engine_impl</code>(注册时使用)与运行时选择的环境变量名不同:</p><table tabindex="0"><thead><tr><th>engine_impl</th><th>选择方式</th></tr></thead><tbody><tr><td>candle</td><td><code>NEURON_LLM_RUNTIME=candle</code> / vision <code>candle-yolo</code> / rerank 各 runtime</td></tr><tr><td>tract</td><td><code>NEURON_ASR_RUNTIME=tract</code>、<code>NEURON_DECISION_RUNTIME=tract</code>、OCR 执行器</td></tr><tr><td>ort</td><td>vision <code>NEURON_VISION_RUNTIME=ort</code>、OCR 执行器 <code>NEURON_OCR_EXECUTOR=ort</code></td></tr><tr><td>sherpa</td><td><code>NEURON_ASR_RUNTIME=sherpa</code></td></tr><tr><td>burn</td><td><code>NEURON_TTS_RUNTIME=voxcpm</code> / <code>voxcpm2</code></td></tr><tr><td>litert</td><td><code>NEURON_LLM_RUNTIME=litert</code></td></tr><tr><td>mistralrs</td><td><code>NEURON_LLM_RUNTIME=mistralrs</code></td></tr><tr><td>mage_vl</td><td><code>NEURON_LLM_RUNTIME=mage_vl</code></td></tr><tr><td>cohere</td><td><code>NEURON_RERANK_RUNTIME=cohere</code>(托管)</td></tr><tr><td>paddle-ocr</td><td>配置注册 <code>capability = &quot;ocr&quot;, engine = &quot;paddle-ocr&quot;</code></td></tr></tbody></table>',29)])])}const p=d(o,[["render",c]]);export{m as __pageData,p as default};
